package com.smarthub.smartmaterial.slider;
import android.content.*;import android.graphics.*;import android.util.AttributeSet;import android.view.*;import com.smarthub.smartmaterial.theme.*;
public class SmartSlider extends View{private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private float value=0,min=0,max=1;private int activeColor,inactiveColor;private OnValueChangeListener listener;public interface OnValueChangeListener{void onValueChanged(SmartSlider slider,float value);}public SmartSlider(Context c){super(c);init();}public SmartSlider(Context c,AttributeSet a){super(c,a);init();}public SmartSlider(Context c,AttributeSet a,int s){super(c,a,s);init();}private void init(){activeColor=SmartTheme.primary(getContext());inactiveColor=SmartTheme.isDark(getContext())?SmartDarkColors.SURFACE_VARIANT:SmartColors.SURFACE_VARIANT;setClickable(true);setFocusable(true);setContentDescription("Slider");setMinimumHeight(dp(48));}private int dp(float v){return SmartDimensions.dp(getContext(),v);}@Override protected void onMeasure(int w,int h){setMeasuredDimension(resolveSize(dp(240),w),resolveSize(dp(48),h));}@Override protected void onDraw(Canvas c){float l=dp(8),r=getWidth()-dp(8),cy=getHeight()/2f,t=dp(4);paint.setStyle(Paint.Style.FILL);paint.setColor(inactiveColor);c.drawRoundRect(l,cy-t/2,r,cy+t/2,t/2,t/2,paint);float f=max==min?0:(value-min)/(max-min);float x=l+(r-l)*Math.max(0,Math.min(1,f));paint.setColor(activeColor);c.drawRoundRect(l,cy-t/2,x,cy+t/2,t/2,t/2,paint);c.drawCircle(x,cy,dp(10),paint);}@Override public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN||e.getActionMasked()==MotionEvent.ACTION_MOVE||e.getActionMasked()==MotionEvent.ACTION_UP){updateFromTouch(e.getX());if(e.getActionMasked()==MotionEvent.ACTION_UP)performClick();return true;}return true;}@Override public boolean performClick(){super.performClick();return true;}private void updateFromTouch(float x){float l=dp(8),r=getWidth()-dp(8),f=(x-l)/(r-l);f=Math.max(0,Math.min(1,f));float nv=min+f*(max-min);if(nv!=value){value=nv;invalidate();if(listener!=null)listener.onValueChanged(this,value);}}public SmartSlider setValue(float v){value=Math.max(min,Math.min(max,v));invalidate();return this;}public float getValue(){return value;}public SmartSlider setRange(float a,float b){if(b<a)throw new IllegalArgumentException("max must be >= min");min=a;max=b;value=Math.max(min,Math.min(max,value));invalidate();return this;}public float getMin(){return min;}public float getMax(){return max;}public SmartSlider setActiveColor(int c){activeColor=c;invalidate();return this;}public SmartSlider setInactiveColor(int c){inactiveColor=c;invalidate();return this;}public SmartSlider setOnValueChangeListener(OnValueChangeListener l){listener=l;return this;}}
